use super::*;
use std::collections::BTreeMap;
use std::path::{Path,PathBuf};
use std::fmt::Write as _;
use std::io::Read;
pub const MAX_CERTIFICATE_BYTES:usize=512*1024;
macro_rules! dependencies { ($($name:literal),+ $(,)?) => { vec![$(($name.to_string(),sha256(include_bytes!(concat!("../../../lib/",$name))))),+] }; }
pub fn runtime_bindings()->Vec<(String,String)>{dependencies!("std/net_session_machine.dlm","std/net_session.dlm","std/net_spec.dlm","std/net_spec_compat.dlm","std/net_codec_runtime.dlm","std/net_transport_policy.dlm","std/net_bytes.dlm","std/native_protocol.dlm","std/native_binary.dlm","std/net_transport.dlm","std/net_quic.dlm","std/net_socket.dlm","std/net_error.dlm","std/native_net.dlm")}
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct NetworkCertificate { pub module:String,pub prefix:String,pub minor:u32,pub source_name:String,pub source_sha256:String,pub descriptor:Vec<u8>,pub executable:Vec<u8>,pub proof:NetworkProofIR,pub dependencies:Vec<(String,String)>,pub binary_sha256:Option<String> }
pub fn hex(bytes:&[u8])->String{bytes.iter().map(|b|format!("{b:02x}")).collect()}
fn unhex(text:&str)->Result<Vec<u8>>{require(text.len()%2==0 && text.len()<=2*MAX_CERTIFICATE_BYTES && text.bytes().all(|c|c.is_ascii_digit()||(b'a'..=b'f').contains(&c)),"noncanonical hex")?;(0..text.len()).step_by(2).map(|i|u8::from_str_radix(&text[i..i+2],16).map_err(|_|invalid("bad hex"))).collect()}
fn digest(text:&str)->Result<String>{require(text.len()==64 && text.bytes().all(|c|c.is_ascii_digit()||(b'a'..=b'f').contains(&c)),"invalid SHA-256 digest")?;Ok(text.into())}
fn identifier(value:&str,limit:usize)->bool{let mut bytes=value.bytes();value.len()<=limit && bytes.next().map(|c|c.is_ascii_alphabetic()||c==b'_').unwrap_or(false) && bytes.all(|c|c.is_ascii_alphanumeric()||c==b'_')}
impl NetworkCertificate {
    pub fn to_text(&self)->String{
        let mut out=format!("DLM-NET-PROOF v1\nmodule {}\nprefix {}\nminor {}\nsource {} {}\ndescriptor {}\nexecutable {}\nreachable {}\nproperties {}\nranks",self.module,self.prefix,self.minor,hex(self.source_name.as_bytes()),self.source_sha256,hex(&self.descriptor),hex(&self.executable),self.proof.reachable,self.proof.properties);
        for rank in &self.proof.ranks{write!(out," {rank}").unwrap();}out.push('\n');for(name,hash)in &self.dependencies{writeln!(out,"dependency {name} {hash}").unwrap();}if let Some(hash)=&self.binary_sha256{writeln!(out,"binary {hash}").unwrap();}out
    }
    pub fn from_text(text:&str,budget:NetworkBudget)->Result<Self>{
        require(text.len()<=budget.max_certificate_bytes.min(MAX_CERTIFICATE_BYTES),"certificate byte limit exceeded")?;let mut lines=text.lines();require(lines.next()==Some("DLM-NET-PROOF v1"),"invalid certificate format")?;let mut headers=BTreeMap::new();let mut dependencies=BTreeMap::new();
        for line in lines{let words=line.split_whitespace().collect::<Vec<_>>();require(words.len()>=2,"empty/malformed certificate line")?;if words[0]=="dependency"{require(words.len()==3 && dependencies.insert(words[1].to_string(),digest(words[2])?).is_none(),"duplicate dependency")?;}else{require(headers.insert(words[0],words[1..].to_vec()).is_none(),"duplicate certificate header")?;}}
        for key in headers.keys(){require(["module","prefix","minor","source","descriptor","executable","reachable","properties","ranks","binary"].contains(key),"unknown certificate header")?;}
        let one=|key:&str|->Result<&str>{let value=headers.get(key).ok_or_else(||invalid(format!("missing {key}")))?;require(value.len()==1,"wrong certificate header arity")?;Ok(value[0])};let module=one("module")?.to_string();let prefix=one("prefix")?.to_string();require(module.split('.').all(|s|identifier(s,128)) && identifier(&prefix,48),"invalid namespace")?;
        let number=|key:&str|->Result<u32>{one(key)?.parse::<u32>().map_err(|_|invalid("invalid U32 header"))};let source=headers.get("source").ok_or_else(||invalid("missing source"))?;require(source.len()==2,"wrong source binding arity")?;let source_name=String::from_utf8(unhex(source[0])?).map_err(|_|invalid("source filename is not UTF-8"))?;require(!source_name.is_empty() && source_name.len()<=255 && !source_name.contains(['/', '\\', ':','\0']) && source_name!="." && source_name!=".." && source_name.ends_with(".dlm"),"invalid source basename")?;
        let source_sha256=digest(source[1])?;let descriptor=unhex(one("descriptor")?)?;let executable=unhex(one("executable")?)?;let ranks=headers.get("ranks").ok_or_else(||invalid("missing ranks"))?;require(ranks.len()<=32,"rank table limit")?;let ranks=ranks.iter().map(|x|x.parse().map_err(|_|invalid("invalid rank"))).collect::<Result<Vec<_>>>()?;let binary_sha256=if headers.contains_key("binary"){Some(digest(one("binary")?)?)}else{None};
        Ok(Self{module,prefix,minor:number("minor")?,source_name,source_sha256,descriptor,executable,proof:NetworkProofIR{reachable:number("reachable")?,properties:number("properties")?,ranks},dependencies:dependencies.into_iter().collect(),binary_sha256})
    }
}
fn csv(words:&[u32])->String{words.iter().map(ToString::to_string).collect::<Vec<_>>().join(",")}
fn boolean(value:u32)->&'static str{if value==0{"false"}else{"true"}}
fn expected(spec:&NetworkSpecIR,machine:&NetworkExecutableIR,minor:u32,module:&str,prefix:&str)->String{
    let w=spec.words;let pure=" guarantees(NoAlloc,NoBlocking,NoIO,BoundedWork)";let mut out=format!("module {module}\nimport std.net_session\nnative {{ fn {prefix}_spec()->NetworkSpec{pure} {{ let mut spec:NetworkSpec=network_spec({});",csv(&w[..4]));
    write!(out,"spec.wire=WireFormat({});spec.transport=TransportRequirements({});spec.resources=ResourceBounds(TransportBounds({},{},{},{}),{},{},U64({}),{});",csv(&w[4..8]),csv(&w[8..11]),w[11],w[12],w[13],w[15],w[16],w[17],((w[18] as u64)<<32)|w[19] as u64,w[20]).unwrap();
    write!(out,"spec.session=SessionContract({},{},{},{},{});spec.security=SecurityRequirements({},{},{},{});spec.proofs=ProofObligations({},{});spec.message_count={};",w[21],w[22],w[23],w[24],boolean(w[25]),w[26],boolean(w[27]),boolean(w[28]),w[29],w[30],w[31],spec.messages.len()).unwrap();
    for(index,message)in spec.messages.iter().enumerate(){let h=message.words;write!(out,"spec.messages[{index}]=message_schema({});spec.messages[{index}].first_minor={};spec.messages[{index}].last_minor={};spec.messages[{index}].field_count={};",csv(&h[..3]),h[3],h[4],h[5]).unwrap();for(i,f)in message.fields.iter().enumerate(){write!(out,"spec.messages[{index}].fields[{i}]=MessageField({});",csv(&f.0)).unwrap();}}
    write!(out,"return spec; }} fn {prefix}_machine()->ProtocolMachine{pure} {{ let mut machine:ProtocolMachine=protocol_machine();machine.initial={};machine.state_count={};machine.transition_count={};",machine.initial,machine.states.len(),machine.transitions.len()).unwrap();
    for(i,state)in machine.states.iter().enumerate(){let s=state.0;write!(out,"machine.states[{i}]=ProtocolState({},{},{},{},{});",s[0],s[1],s[2],boolean(s[3]),boolean(s[4])).unwrap();}for(i,edge)in machine.transitions.iter().enumerate(){let t=edge.0;write!(out,"machine.transitions[{i}]=ProtocolTransition({},{},{},{},{},{},{},{});",t[0],t[1],t[2],t[3],t[4],t[5],t[6],boolean(t[7])).unwrap();}
    write!(out,"return machine; }} fn {prefix}_open(initiator:Bool,choice:TransportChoice,target:TransportTarget,cancel:&Resource<OpaqueHandle,net_cancel_dispose>)->ProtocolSession {{ return protocol_open({prefix}_spec(),{prefix}_machine(),{minor},initiator,choice,target,cancel); }} fn {prefix}_adopt(transport:TransportSession,initiator:Bool)->ProtocolSession {{ return protocol_adopt(move transport,{prefix}_spec(),{prefix}_machine(),{minor},initiator); }} }}").unwrap();out
}
fn tokens(source:&str)->Result<Vec<&str>>{
    let data=source.as_bytes();let mut position=0;let mut result=Vec::new();while position<data.len(){let start=position;let c=data[position];if c.is_ascii_whitespace(){position+=1;continue;}if data[position..].starts_with(b"//"){while position<data.len() && data[position]!=b'\n'{position+=1;}continue;}if data[position..].starts_with(b"/*"){position+=2;let mut depth=1usize;while position<data.len() && depth!=0{if data[position..].starts_with(b"/*"){depth+=1;position+=2;}else if data[position..].starts_with(b"*/"){depth-=1;position+=2;}else{position+=1;}}require(depth==0,"unterminated source comment")?;continue;}
        require(c!=b'\'' && c!=b'"' && c.is_ascii(),"source token is outside permitted wrapper grammar")?;if c.is_ascii_alphanumeric()||c==b'_'{position+=1;while position<data.len() && (data[position].is_ascii_alphanumeric()||data[position]==b'_'){position+=1;}}
        else{position+=1;if position<data.len() && [b"->".as_slice(),b"==",b"!=",b"<=",b">=",b"&&",b"||",b".."].iter().any(|p|data[start..].starts_with(p)){position+=1;}}result.push(&source[start..position]);}Ok(result)
}
pub fn source_matches(source:&str,spec:&NetworkSpecIR,machine:&NetworkExecutableIR,minor:u32,module:&str,prefix:&str)->Result<()>{let template=expected(spec,machine,minor,module,prefix);require(tokens(source)?==tokens(&template)?,"source differs from the independently admitted executable rules")}
pub(crate) fn read(path:&Path,maximum:usize)->Result<Vec<u8>>{let mut input=std::fs::File::open(path).map_err(|e|invalid(format!("{}: {e}",path.display())))?;let mut bytes=Vec::new();input.by_ref().take(maximum as u64+1).read_to_end(&mut bytes).map_err(|e|invalid(e.to_string()))?;require(bytes.len()<=maximum,"file byte limit exceeded")?;Ok(bytes)}
pub fn check_bundle(certificate_path:&Path,library:&Path,binary:Option<&Path>,budget:NetworkBudget)->Result<NetworkAudit>{
    let bytes=read(certificate_path,budget.max_certificate_bytes.min(MAX_CERTIFICATE_BYTES))?;let text=std::str::from_utf8(&bytes).map_err(|_|invalid("certificate is not UTF-8"))?;let certificate=NetworkCertificate::from_text(text,budget)?;let spec=NetworkSpecIR::from_bytes(&certificate.descriptor)?;let machine=NetworkExecutableIR::from_bytes(&certificate.executable)?;
    let mut report=check_network_proof(&spec,&machine,certificate.minor,&certificate.proof,budget)?;let expected=runtime_bindings().into_iter().collect::<BTreeMap<_,_>>();let actual=certificate.dependencies.iter().cloned().collect::<BTreeMap<_,_>>();require(actual==expected,"certificate changes the pinned runtime closure")?;
    for(name,hash)in &expected{require(sha256(&read(&library.join(name),1024*1024)?)==*hash,"runtime library differs from kernel pins")?;}
    let parent=certificate_path.parent().unwrap_or_else(||Path::new("."));let source_path=parent.join(&certificate.source_name);let source=read(&source_path,2*1024*1024)?;require(sha256(&source)==certificate.source_sha256,"source binding mismatch")?;
    let path=|suffix:&str|PathBuf::from(format!("{}{suffix}",source_path.display()));require(read(&path(".dns"),16904)?==certificate.descriptor && read(&path(".state"),8848)?==certificate.executable,"descriptor/machine sidecar binding mismatch")?;
    source_matches(std::str::from_utf8(&source).map_err(|_|invalid("source is not UTF-8"))?,&spec,&machine,certificate.minor,&certificate.module,&certificate.prefix)?;
    match(&certificate.binary_sha256,binary){(Some(hash),Some(path))=>{require(sha256(&read(path,256*1024*1024)?)==*hash,"binary binding mismatch")?;report.binary_sha256=Some(hash.clone());},(Some(_),None)=>return Err(invalid("certificate binds a binary; pass --binary")),(None,Some(_))=>return Err(invalid("certificate has no binary binding")),(None,None)=>{}}
    report.source_sha256=certificate.source_sha256;Ok(report)
}
